alter table supplier_credit_note add column if not exists note_date date,add column if not exists fiscal_period_id bigint references fiscal_periods,add column if not exists currency_id bigint references currencies,add column if not exists exchange_rate numeric(24,10) not null default 1,add column if not exists memo text,add column if not exists journal_id bigint references journal,add column if not exists location_id bigint references locations;
alter table supplier_debit_note add column if not exists note_date date,add column if not exists fiscal_period_id bigint references fiscal_periods,add column if not exists currency_id bigint references currencies,add column if not exists exchange_rate numeric(24,10) not null default 1,add column if not exists memo text,add column if not exists journal_id bigint references journal,add column if not exists location_id bigint references locations;
create table if not exists supplier_note_line(line_id bigint generated always as identity primary key,note_kind text not null check(note_kind in('CREDIT','DEBIT')),note_id bigint not null,account_id bigint not null references chart_accounts,amount numeric(24,6) not null check(amount>0),tax_code_id bigint references tax_codes,tax_rate numeric(12,6) not null default 0,tax_amount numeric(24,6) not null default 0,gross_amount numeric(24,6) not null,note text,department_id bigint references departments,cost_center_id bigint references cost_centers,class_id bigint references classes,financial_creditor_id bigint references financial_creditors,related_company_id bigint references related_companies);
alter table supplier_note_line enable row level security;drop policy if exists supplier_note_line_access on supplier_note_line;create policy supplier_note_line_access on supplier_note_line for select to authenticated using(exists(select 1 from supplier_credit_note n join supplier_invoice i using(invoice_id) where note_kind='CREDIT' and n.cn_id=note_id and i.subsidiary_id=active_subsidiary_id()) or exists(select 1 from supplier_debit_note n join supplier_invoice i using(invoice_id) where note_kind='DEBIT' and n.dn_id=note_id and i.subsidiary_id=active_subsidiary_id()));grant select on supplier_note_line to authenticated;
create or replace function save_supplier_note(p_kind text,p_payload jsonb,p_target_id bigint default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
#variable_conflict use_column
declare sid bigint:=active_subsidiary_id();kind text:=upper(p_kind);iid bigint:=(p_payload->>'invoice_id')::bigint;nid bigint:=p_target_id;tid bigint;jid bigint;tt bigint;status_key bigint;loc bigint;ap bigint;line jsonb;amount numeric;tax numeric;gross numeric;total numeric:=0;tax_account bigint;number text;original supplier_invoice%rowtype;sign_debit boolean;
begin
 if kind not in('CREDIT','DEBIT') then raise exception 'Tipo de nota inválido.';end if;if sid is null or not exists(select 1 from user_subsidiaries where user_id=app_user_id() and subsidiary_id=sid) then raise exception 'No tiene acceso a la subsidiaria activa.';end if;select * into original from supplier_invoice where invoice_id=iid and subsidiary_id=sid;if not found then raise exception 'La factura relacionada no existe en la subsidiaria activa.';end if;
 if jsonb_array_length(coalesce(p_payload->'lines','[]'))<1 then raise exception 'La nota debe contener líneas.';end if;sign_debit:=kind='DEBIT';
 if not exists(select 1 from fiscal_periods where fiscal_period_id=(p_payload->>'fiscal_period_id')::bigint and subsidiary_id=sid and not is_closed and not coalesce(ap_closed,false) and (p_payload->>'note_date')::date between start_date and end_date) then raise exception 'El período de Compras no está abierto.';end if;
 select transaction_type_id into tt from transaction_types where abbreviation=case when kind='CREDIT' then 'NC_PRO' else 'ND_PRO' end limit 1;select status_id into status_key from status order by case upper(code) when 'CONTABILIZADO' then 1 when 'APROBADO' then 2 else 3 end,status_id limit 1;loc:=original.location_id;if loc is null then select l.location_id into loc from locations l join location_subsidiaries ls using(location_id) where ls.subsidiary_id=sid order by l.name limit 1;end if;select a.account_id into ap from chart_accounts a join account_subsidiaries s using(account_id) where s.subsidiary_id=sid and s.is_active and a.category='Pasivo' and lower(a.account_name) ~ '(cuenta.*por pagar|proveedor.*por pagar)' order by a.account_number limit 1;
 for line in select * from jsonb_array_elements(p_payload->'lines') loop if not exists(select 1 from chart_accounts a join account_subsidiaries s using(account_id) where a.account_id=(line->>'account_id')::bigint and s.subsidiary_id=sid and s.is_active and a.accepts_entries and not a.is_inactive) then raise exception 'La cuenta seleccionada no está disponible en la subsidiaria activa.';end if;if nullif(line->>'tax_code_id','') is not null and not exists(select 1 from tax_code_subsidiaries where tax_code_id=(line->>'tax_code_id')::bigint and subsidiary_id=sid) then raise exception 'El código de impuesto seleccionado no pertenece a la subsidiaria activa.';end if;amount:=(line->>'amount')::numeric;if amount<=0 then raise exception 'El importe de cada línea debe ser mayor que cero.';end if;tax:=round(amount*coalesce(nullif(line->>'tax_rate','')::numeric,0)/100,6);total:=total+amount+tax;end loop;if kind='CREDIT' and total+coalesce((select sum(amount) from supplier_credit_note where invoice_id=iid and cn_id<>coalesce(nid,-1)),0)>original.total_amount then raise exception 'Las notas de crédito no pueden superar el total de la factura original.';end if;
 if nid is null then begin number:=next_transaction_number(tt,sid);exception when others then number:=(case when kind='CREDIT' then 'NC_PRO-' else 'ND_PRO-' end)||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS');end;insert into "transaction"(tran_number,tran_date,transaction_type_id,subsidiary_id,currency_id,exchange_rate,fiscal_period_id,total_amount,status_id,supplier_id) values(number,(p_payload->>'note_date')::date,tt,sid,(p_payload->>'currency_id')::bigint,(p_payload->>'exchange_rate')::numeric,(p_payload->>'fiscal_period_id')::bigint,total,status_key,original.supplier_id) returning transaction_id into tid;insert into journal(journal_number,journal_date,transaction_id,subsidiary_id,currency_id,fiscal_period_id,exchange_rate,memo,journal_type,location_id,total_debit,total_credit,status) values(number,(p_payload->>'note_date')::date,tid,sid,(p_payload->>'currency_id')::bigint,(p_payload->>'fiscal_period_id')::bigint,(p_payload->>'exchange_rate')::numeric,p_payload->>'memo',case when kind='CREDIT' then 'Nota de crédito proveedor' else 'Nota de débito proveedor' end,loc,total,total,'CONTABILIZADO') returning journal_id into jid;if kind='CREDIT' then insert into supplier_credit_note(cn_number,transaction_id,supplier_id,invoice_id,amount,note_date,fiscal_period_id,currency_id,exchange_rate,memo,journal_id,location_id) values(p_payload->>'note_number',tid,original.supplier_id,iid,total,(p_payload->>'note_date')::date,(p_payload->>'fiscal_period_id')::bigint,(p_payload->>'currency_id')::bigint,(p_payload->>'exchange_rate')::numeric,p_payload->>'memo',jid,loc) returning cn_id into nid;else insert into supplier_debit_note(dn_number,transaction_id,supplier_id,invoice_id,amount,note_date,fiscal_period_id,currency_id,exchange_rate,memo,journal_id,location_id) values(p_payload->>'note_number',tid,original.supplier_id,iid,total,(p_payload->>'note_date')::date,(p_payload->>'fiscal_period_id')::bigint,(p_payload->>'currency_id')::bigint,(p_payload->>'exchange_rate')::numeric,p_payload->>'memo',jid,loc) returning dn_id into nid;end if;else if kind='CREDIT' then select transaction_id,journal_id into tid,jid from supplier_credit_note where cn_id=nid and invoice_id=iid;update supplier_credit_note set cn_number=p_payload->>'note_number',amount=total,note_date=(p_payload->>'note_date')::date,fiscal_period_id=(p_payload->>'fiscal_period_id')::bigint,currency_id=(p_payload->>'currency_id')::bigint,exchange_rate=(p_payload->>'exchange_rate')::numeric,memo=p_payload->>'memo' where cn_id=nid;else select transaction_id,journal_id into tid,jid from supplier_debit_note where dn_id=nid and invoice_id=iid;update supplier_debit_note set dn_number=p_payload->>'note_number',amount=total,note_date=(p_payload->>'note_date')::date,fiscal_period_id=(p_payload->>'fiscal_period_id')::bigint,currency_id=(p_payload->>'currency_id')::bigint,exchange_rate=(p_payload->>'exchange_rate')::numeric,memo=p_payload->>'memo' where dn_id=nid;end if;update "transaction" set tran_date=(p_payload->>'note_date')::date,currency_id=(p_payload->>'currency_id')::bigint,exchange_rate=(p_payload->>'exchange_rate')::numeric,fiscal_period_id=(p_payload->>'fiscal_period_id')::bigint,total_amount=total where transaction_id=tid;update journal set journal_date=(p_payload->>'note_date')::date,currency_id=(p_payload->>'currency_id')::bigint,exchange_rate=(p_payload->>'exchange_rate')::numeric,fiscal_period_id=(p_payload->>'fiscal_period_id')::bigint,memo=p_payload->>'memo',total_debit=total,total_credit=total where journal_id=jid;delete from journal_line where journal_id=jid;delete from supplier_note_line where note_kind=kind and note_id=nid;end if;
 for line in select * from jsonb_array_elements(p_payload->'lines') loop amount:=(line->>'amount')::numeric;tax:=round(amount*coalesce(nullif(line->>'tax_rate','')::numeric,0)/100,6);gross:=amount+tax;insert into supplier_note_line(note_kind,note_id,account_id,amount,tax_code_id,tax_rate,tax_amount,gross_amount,note,department_id,cost_center_id,class_id,financial_creditor_id,related_company_id) values(kind,nid,(line->>'account_id')::bigint,amount,nullif(line->>'tax_code_id','')::bigint,coalesce(nullif(line->>'tax_rate','')::numeric,0),tax,gross,line->>'note',nullif(line->>'department_id','')::bigint,nullif(line->>'cost_center_id','')::bigint,nullif(line->>'class_id','')::bigint,nullif(line->>'financial_creditor_id','')::bigint,nullif(line->>'related_company_id','')::bigint);insert into journal_line(journal_id,account_id,debit,credit,debit_fx,credit_fx,note,department_id,class_id,location_id,cost_center_id,financial_creditor_id,related_company_id) values(jid,(line->>'account_id')::bigint,case when sign_debit then amount else 0 end,case when sign_debit then 0 else amount end,case when sign_debit then amount else 0 end,case when sign_debit then 0 else amount end,line->>'note',nullif(line->>'department_id','')::bigint,nullif(line->>'class_id','')::bigint,loc,nullif(line->>'cost_center_id','')::bigint,nullif(line->>'financial_creditor_id','')::bigint,nullif(line->>'related_company_id','')::bigint);if tax>0 then select ty.asset_account_id into tax_account from tax_codes tc join tax_types ty using(tax_type_id) where tc.tax_code_id=(line->>'tax_code_id')::bigint;insert into journal_line(journal_id,account_id,debit,credit,debit_fx,credit_fx,note,location_id) values(jid,tax_account,case when sign_debit then tax else 0 end,case when sign_debit then 0 else tax end,case when sign_debit then tax else 0 end,case when sign_debit then 0 else tax end,'Impuesto',loc);end if;end loop;insert into journal_line(journal_id,account_id,debit,credit,debit_fx,credit_fx,note,entity_type,supplier_id,location_id) values(jid,ap,case when sign_debit then 0 else total end,case when sign_debit then total else 0 end,case when sign_debit then 0 else total end,case when sign_debit then total else 0 end,'Cuenta por pagar','Proveedor',original.supplier_id,loc);perform sync_journal_gl_impacts(jid);return jsonb_build_object('noteId',nid,'journalId',jid,'transactionNumber',number,'total',total);
end$$;revoke all on function save_supplier_note(text,jsonb,bigint) from public;grant execute on function save_supplier_note(text,jsonb,bigint) to authenticated;
